&lt;p&gt;&lt;strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335557856&amp;quot;:16777215}&quot;&gt;&amp;nbsp;WHAT YOU&#39;LL NEED&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Bachelor&#39;s degree in Electrical, Mechatronics,&amp;nbsp;Aerospace&amp;nbsp;or related Engineering field&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335557856&amp;quot;:16777215}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
